import torch
def binary_metrics(logits,labels):
    pred=logits>=0
    truth=labels==1
    tp=(pred&truth).sum().item()
    fp=(pred&~truth).sum().item()
    fn=(~pred&truth).sum().item()
    return {"precision":tp/(tp+fp) if tp+fp else 0.0,"recall":tp/(tp+fn) if tp+fn else 0.0,"f1":2*tp/(2*tp+fp+fn) if 2*tp+fp+fn else 0.0}

